(function(root){const schema=typeof module!=='undefined'?require('./shot-schema.js'):root.ShotSchema;const copy=x=>JSON.parse(JSON.stringify(x));const previousMerge=schema.merge,previousReconcile=schema.reconcile,previousPack=schema.pack;
const hierarchy=raw=>Array.isArray(raw?.shots)&&raw.shots.some(s=>Array.isArray(s.sub_shots));
function naturalPrompt(text,project){let out=String(text||'');for(const c of project.characters||[]){const id=c.id||c.character_id;if(id)out=out.replace(new RegExp('\\b'+id.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','g'),c.name||'角色');}for(const scene of project.scenes||[]){const id=scene.id||scene.scene_id;if(id)out=out.replace(new RegExp('\\b'+id+'\\b','g'),scene.name||'场景');}return out;}
function structuredPrompt(text){return /(?:subject_definitions|integrated_multimodal_description|detailed_description)\s*[:：>]/i.test(String(text||''));}
function rebuild(main,project){
 main.generation??={};main.video_generation??={};
 // Dialogue data follows the edited child shots; video prose requires review.
 main.audio??={};const previous=main.audio.dialogues||[];
 main.audio.dialogues=(main.sub_shots||[]).filter(s=>s.dialogue).map(s=>({...previous.find(d=>d.sub_shot_id===s.sub_shot_id),...copy(s.dialogue),sub_shot_id:s.sub_shot_id}));
 const p=main.generation.video_methods;
 // Never flatten H3 sections, endpoint instructions, speaker tags or custom prose.
 const preserved=p||structuredPrompt(main.video_generation.prompt)||structuredPrompt(main.generation.video_prompt);
 if(!preserved)rebuildLegacy(main,project);
 else {main.video_generation.prompt=p?.reference_images?.video_prompt??main.video_generation.prompt??main.generation.video_prompt??'';main.generation.video_prompt=main.video_generation.prompt;}
 main.generationReviewRequired=true;
 if(root.ShotMethods?.invalidate)root.ShotMethods.invalidate(main);
 else {main.videoPlanReviews={};for(const pos of ['first','last'])if(main.frameImages?.[pos])main.frameImages[pos].needsReview=true;}
}
function rebuildLegacy(main,project){const intro=main.picture_inputs.map(p=>{const name=p.type==='scene'?project.scenes?.find(s=>s.id===p.ref_id)?.name:project.characters?.find(c=>c.id===p.ref_id)?.name;return p.picture+' 为'+(name||'输入的')+(p.type==='scene'?'场景':'角色')+'参考图。'}).join(' ');main.video_generation.prompt=intro+' 保持场景结构、角色身份与服装一致，不复制多视图排版，不重复角色。\n'+main.sub_shots.map(s=>{const d=s.dialogue;const name=d?project.characters?.find(c=>c.id===d.speaker_id)?.name||'画外声音':'';return s.start_offset_seconds+'–'+s.end_offset_seconds+'秒：'+s.visual_action+(d?'；'+name+(d.offscreen?'（画外声音，不在画面中出现）':'')+'说：“'+d.text+'”':'')+'。';}).join('\n')+'\n'+(main.generation.direction_prompt||'保持本项目既定画风、人物身份、场景结构与对白原文。环境声与音乐按本镜头音轨计划执行。');main.generation.video_prompt=main.video_generation.prompt;}
function normalize(main,project){const duration=Number(main.duration_seconds??main.duration);if(!Number.isFinite(duration)||duration<=0||duration>Number(project.max_main_shot_duration_seconds||15))throw Error(main.shot_id+' 主分镜时长不合法');if(!Array.isArray(main.sub_shots)||!main.sub_shots.length)throw Error(main.shot_id+' 缺少子分镜');const mapped={...copy(main),duration,action:main.sub_shots.map(s=>s.visual_action).join('；'),picture_inputs:(main.picture_inputs||[]).map(p=>({...p,picture:p.picture||p.tag}))};const out=schema.normalize(mapped,0);out.generation??={};out.prompt=main.generation?.image_prompt||'';out.image_generation={prompt:out.prompt,negative_prompt:main.generation?.negative_prompt||''};out.video_generation={model:main.generation?.model||'MiniMax H3',prompt:naturalPrompt(main.generation?.video_prompt,project)};for(const sub of out.sub_shots){if(sub.dialogue?.offscreen){const speaker=project.characters?.find(c=>c.id===sub.dialogue.speaker_id)?.name;if(speaker&&!out.video_generation.prompt.includes(speaker+'（画外声音'))out.video_generation.prompt=out.video_generation.prompt.replaceAll(speaker,speaker+'（画外声音，不在画面中出现）');}}out.generation.video_prompt=out.video_generation.prompt;out.description=out.action;out.camera='按子分镜时间轴执行';let cursor=0;const ids=new Set();for(const sub of out.sub_shots){if(!sub.sub_shot_id||ids.has(sub.sub_shot_id))throw Error('子分镜编号缺失或重复');ids.add(sub.sub_shot_id);const start=Number(sub.start_offset_seconds),end=Number(sub.end_offset_seconds),length=Number(sub.duration_seconds);if(![start,end,length].every(Number.isFinite)||length<=0||Math.abs(start-cursor)>1e-6||Math.abs(end-start-length)>1e-6)throw Error(sub.sub_shot_id+' 时间轴不连续或时长不一致');if(sub.dialogue!==null&&sub.dialogue!==undefined&&(typeof sub.dialogue.text!=='string'||typeof sub.dialogue.speaker_id!=='string'))throw Error(sub.sub_shot_id+' 对白格式不正确');cursor=end;}if(Math.abs(cursor-duration)>1e-6)throw Error(main.shot_id+' 子分镜总时长不等于主分镜');return out;}
schema.reconcile=function(project){if(!project.shotScript?.hierarchical)return previousReconcile(project);let total=0;const warnings=[];for(const main of project.shots){let offset=0;for(const sub of main.sub_shots){sub.start_offset_seconds=offset;offset=Math.round((offset+Number(sub.duration_seconds))*1000)/1000;sub.end_offset_seconds=offset;}main.duration=main.duration_seconds=offset;main.start_time=main.start_time_seconds=total;total=Math.round((total+offset)*1000)/1000;main.end_time=main.end_time_seconds=total;main.description=main.action=main.sub_shots.map(s=>s.visual_action).join('；');main.generation.image_prompt=main.prompt;main.image_generation.prompt=main.prompt;main.generation.video_prompt=main.video_generation.prompt;if(offset>(project.shotScript.max_main_shot_duration_seconds||15))warnings.push(main.shot_id+' 超过主分镜时长上限');}project.shotScript.actual_duration_seconds=total;return{duration:total,warnings};};
schema.merge=function(project,raw){if(!hierarchy(raw))return previousMerge(project,raw);if(raw.project_id&&project.project_id&&raw.project_id!==project.project_id)throw Error('project_id 与当前项目不同');const next=copy(project),mains=raw.shots.map(s=>normalize(s,{...project,max_main_shot_duration_seconds:raw.max_main_shot_duration_seconds}));const ids=new Set();for(const main of mains){if(ids.has(main.id))throw Error('重复主分镜 '+main.id);ids.add(main.id);}const same=project.shotScript?.hierarchical;const changed=!same||JSON.stringify(project.shots.map(s=>({id:s.id,sub_shots:s.sub_shots,generation:s.generation})))!==JSON.stringify(mains.map(s=>({id:s.id,sub_shots:s.sub_shots,generation:s.generation})));if(project.shots?.length&&changed){next.shotScriptArchives??=[];next.shotScriptArchives.push({id:'archive-'+Date.now(),saved_at:new Date().toISOString(),version:project.shotScript?.version||'3.1',shots:copy(project.shots),shotScript:copy(project.shotScript||{})});}if(same)for(const main of mains){const old=project.shots.find(s=>s.id===main.id);if(!old)continue;const equivalent=JSON.stringify(old.sub_shots)===JSON.stringify(main.sub_shots)&&old.video_generation?.prompt===main.video_generation.prompt;if(equivalent)for(const k of ['versions','videoVersions','videoJob','activeVideoId','videoResolution','pictureSelections'])if(old[k]!==undefined)main[k]=copy(old[k]);}
next.shots=mains;next.shotScript=copy(raw);delete next.shotScript.shots;next.shotScript.hierarchical=true;next.shotScript.schema_type='shot_script';next.shotScript.generation_clips=[];const result=schema.reconcile(next);return{project:next,count:mains.length,sub_count:mains.reduce((n,s)=>n+s.sub_shots.length,0),...result};};
schema.pack=function(project){if(!project.shotScript?.hierarchical)return previousPack(project);const out={...copy(project.shotScript),project_id:project.project_id,shots:copy(project.shots)};delete out.hierarchical;delete out.generation_clips;out.shots.forEach(s=>{s.picture_inputs=s.picture_inputs.map(p=>({...p,tag:p.picture}));s.generation.image_prompt=s.prompt;s.generation.video_prompt=s.video_generation.prompt;});return out;};schema.isStructuredPrompt=structuredPrompt;schema.isHierarchical=hierarchy;schema.rebuildMainPrompt=rebuild;schema.naturalPrompt=naturalPrompt;if(typeof module!=='undefined')module.exports=schema;
})(typeof window==='undefined'?globalThis:window);
